import re, subprocess

def tokenize(s):
    toks=[]
    i=0
    while i<len(s):
        c=s[i]
        if c.isalnum() or c=='_':
            j=i
            while j<len(s) and (s[j].isalnum() or s[j]=='_'):
                j+=1
            toks.append(s[i:j]); i=j
        elif c in ' \t':
            j=i
            while j<len(s) and s[j] in ' \t':
                j+=1
            toks.append(s[i:j]); i=j
        elif c=='\n':
            toks.append('\n'); i+=1
        else:
            toks.append(c); i+=1
    return toks

def parse_line(line):
    tokens=re.split(rb'(\x1b\[[0-9;]*m)', line)
    segs=[]
    pending=[]
    for tok in tokens:
        if not tok:
            continue
        if tok.startswith(b'\x1b['):
            pending.append(tok[2:-1].decode())
        else:
            is_refine = any(c in ('41','42') for c in pending)
            segs.append((pending.copy(), tok, is_refine))
            pending=[]
    return segs

def analyze_case(r_str, a_str):
    diff="--- a\n+++ b\n@@ -1,1 +1,1 @@\n-%s\n+%s\n" % (r_str, a_str)
    p=subprocess.Popen(["./executable"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out,_=p.communicate(diff.encode())
    # Find removed and added lines
    for line in out.split(b'\n'):
        if b'\x1b[31m-' in line:
            segs=parse_line(line)
            print("removed line raw:", line)
            for codes, txt, is_ref in segs:
                print(" seg codes",codes,"txt",repr(txt),"refine",is_ref)
            # Content segs excluding prefix
            content_segs = [(txt, is_ref) for codes, txt, is_ref in segs if txt not in (b'-',b'+',b'')]
            # Now map tokens
            # Build list of (token, is_common) for this line
            per_token=[]
            for seg_txt, is_ref in content_segs:
                # seg_txt is bytes
                text = seg_txt.decode()
                # tokenize text
                toks = tokenize(text)
                for tok in toks:
                    per_token.append((tok, not is_ref))
            print(" per_token", per_token)
            print(" expected tokens", tokenize(r_str))
        if b'\x1b[32m+' in line:
            segs=parse_line(line)
            print("added line raw:", line)
            for codes, txt, is_ref in segs:
                print(" seg codes",codes,"txt",repr(txt),"refine",is_ref)
            content_segs = [(txt, is_ref) for codes, txt, is_ref in segs if txt not in (b'-',b'+',b'')]
            per_token=[]
            for seg_txt, is_ref in content_segs:
                text = seg_txt.decode()
                toks = tokenize(text)
                for tok in toks:
                    per_token.append((tok, not is_ref))
            print(" per_token added", per_token)
            print(" expected tokens", tokenize(a_str))

