    diffr reads from standard input and writes to standard output.

    Typical usage is for interactive use of diff:
    diff -u <file1> <file2> | diffr
    git show | diffr

OPTIONS:
        --colors <COLOR_SPEC>...    Configure color settings.
        --line-numbers              Display line numbers.
    -h, --help                      Prints help information
    -V, --version                   Prints version information
"""

# Faces
FACES = ["added","removed","refine-added","refine-removed"]

# Default styles
# style dict: fg, bg, bold, italic, underline, dimmed, intense
# fg/bg: None, or str name, or int 0-255, or tuple (r,g,b)
def default_styles():
    return {
        "added": {"fg": "green", "bg": None, "bold": False, "italic": False, "underline": False, "dimmed": False, "intense": False},
        "removed": {"fg": "red", "bg": None, "bold": False, "italic": False, "underline": False, "dimmed": False, "intense": False},
        "refine-added": {"fg": (255,255,255), "bg": "green", "bold": True, "italic": False, "underline": False, "dimmed": False, "intense": False},
        "refine-removed": {"fg": (255,255,255), "bg": "red", "bold": True, "italic": False, "underline": False, "dimmed": False, "intense": False},
    }

NAMED_COLORS = {"black","blue","green","red","cyan","magenta","yellow","white"}
NAMED_FG_MAP = {"black":30,"blue":34,"green":32,"red":31,"cyan":36,"magenta":35,"yellow":33,"white":37}
NAMED_BG_MAP = {"black":40,"blue":44,"green":42,"red":41,"cyan":46,"magenta":45,"yellow":43,"white":47}
BRIGHT_FG_MAP = {"black":8,"blue":12,"green":10,"red":9,"cyan":14,"magenta":13,"yellow":11,"white":15}
BRIGHT_BG_MAP = {"black":8,"blue":12,"green":10,"red":9,"cyan":14,"magenta":13,"yellow":11,"white":15}

def eprint(s):
    sys.stderr.write(s)
    sys.stderr.flush()

def print_help(long=False):
    txt = HELP_LONG if long else HELP_SHORT
    # help goes to stdout for --help/-h per observed: stdout
    sys.stdout.write(txt)
    if not txt.endswith("\n"):
        sys.stdout.write("\n")

def print_version():
    # version goes to stderr
    eprint(f"diffr {VERSION}\n")

def error_exit(msg, code=255):
    eprint(msg + "\n")
    sys.exit(code)

def bad_arg(msg):
    # prints bad argument + help short to stderr and exits 2
    eprint(f"bad argument: '{msg}'\n")
    # help short version is printed after bad argument? The observed bad argument prints diffr version + usage short
    # Actually it prints HELP_SHORT but starting from "diffr 0.1.5\n..."
    eprint(HELP_SHORT)
    sys.exit(2)

def option_requires(arg):
    eprint(f"option requires an argument: '{arg}'\n")
    sys.exit(2)

# Color parsing helpers
def parse_color_value(val):
    if val == "none":
        return None
    low = val.lower()
    if low in NAMED_COLORS:
        return low
    # check for RGB triple
    if "," in val:
        parts = val.split(",")
        if len(parts) != 3:
            error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'", 255)
        rgb = []
        for p in parts:
            p = p.strip()
            if p.lower().startswith("0x"):
                # hex
                hexpart = p[2:]
                if not hexpart:
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                if len(hexpart)>2:
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                try:
                    v = int(hexpart, 16)
                except:
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                if not (0 <= v <= 255):
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                rgb.append(v)
            else:
                # decimal
                if not re.fullmatch(r"[0-9]+", p):
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                try:
                    v = int(p, 10)
                except:
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                if not (0 <= v <= 255):
                    error_exit(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{val}'",255)
                rgb.append(v)
        return tuple(rgb)
    else:
        # single value: ansi256 or hex
        # check hex pattern 0x...
        if re.fullmatch(r"0[xX][0-9a-fA-F]{1,2}", val):
            try:
                v = int(val, 16)
            except:
                error_exit(f"unexpected color value: unrecognized color name '{val}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",255)
            if 0 <= v <= 255:
                return v
            else:
                # hex out of range with 1-2 digits shouldn't happen, but if 0x100 not matched, we wouldn't be here
                error_exit(f"unexpected color value: unrecognized color name '{val}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",255)
        elif re.fullmatch(r"[0-9]+", val):
            try:
                v = int(val, 10)
            except:
                error_exit(f"unexpected color value: unrecognized color name '{val}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",255)
            if 0 <= v <= 255:
                return v
            else:
                error_exit(f"unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{val}'",255)
        else:
            # not numeric, treat as name
            error_exit(f"unexpected color value: unrecognized color name '{val}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",255)

def apply_colors(face_styles, spec):
    # spec is string like "added:foreground:blue:bold"
    # split by colon
    if spec == "":
        error_exit("unexpected face name: got '', expected added|refine-added|removed|refine-removed",255)
    parts = spec.split(":")
    face = parts[0]
    if face not in FACES:
        error_exit(f"unexpected face name: got '{face}', expected added|refine-added|removed|refine-removed",255)
    tokens = parts[1:]
    # if no attributes? e.g., "added" alone? Then error? The spec should have at least one attribute after colon. But our split would give tokens=[] if spec=="added". That would be missing attributes? Might be considered error? We can treat as error about attribute name empty.
    # However spec "added:" gives tokens=[""] -> should error about attribute name ''
    if len(tokens)==0:
        # This would be like "added" with no colon? Actually spec must contain colon after face. If no colon, then parts len 1, tokens empty -> we should error? The original for "added" without colon maybe considered missing? But our test for "added:" gave error unexpected attribute name got ''.
        # So we can handle tokens empty as error
        error_exit(f"unexpected attribute name: got '', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",255)
    # iterate tokens
    i=0
    style = face_styles[face]
    while i < len(tokens):
        tok = tokens[i]
        if tok == "foreground" or tok == "background":
            if i+1 >= len(tokens):
                error_exit(f"error parsing color: missing color value for face '{face}'",255)
            color_val = tokens[i+1]
            # For empty color_val, parse will error appropriately
            parsed = parse_color_value(color_val)
            if tok == "foreground":
                style["fg"] = parsed
            else:
                style["bg"] = parsed
            i+=2
        elif tok == "":
            error_exit(f"unexpected attribute name: got '', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",255)
        elif tok in ("italic","noitalic","bold","nobold","dimmed","nodimmed","intense","nointense","underline","nounderline","none"):
            if tok == "italic":
                style["italic"] = True
            elif tok == "noitalic":
                style["italic"] = False
            elif tok == "bold":
                style["bold"] = True
            elif tok == "nobold":
                style["bold"] = False
            elif tok == "dimmed":
                style["dimmed"] = True
            elif tok == "nodimmed":
                style["dimmed"] = False
            elif tok == "intense":
                style["intense"] = True
            elif tok == "nointense":
                style["intense"] = False
            elif tok == "underline":
                style["underline"] = True
            elif tok == "nounderline":
                style["underline"] = False
            elif tok == "none":
                # clear all
                style["fg"] = None
                style["bg"] = None
                style["bold"] = False
                style["italic"] = False
                style["underline"] = False
                style["dimmed"] = False
                style["intense"] = False
                # Note: "none" should clear and possibly ignore following? But we continue. Subsequent attributes after none should apply? Example "added:none:foreground:blue" gave blue. So after clearing, continue.
            i+=1
        else:
            error_exit(f"unexpected attribute name: got '{tok}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",255)

def ansi_for_style(style):
    # returns list of SGR code strings (without ESC), each as separate code
    codes = []
    if style.get("bold"):
        codes.append("1")
    if style.get("dimmed"):
        codes.append("2")
    if style.get("italic"):
        codes.append("3")
    if style.get("underline"):
        codes.append("4")
    # Note: intense is not a separate SGR, handled via color mapping
    fg = style.get("fg")
    bg = style.get("bg")
    intense = style.get("intense", False)
    # fg
    if fg is not None:
        if isinstance(fg, str):
            if intense:
                # map to bright
                v = BRIGHT_FG_MAP[fg]
                codes.append(f"38;5;{v}")
            else:
                codes.append(str(NAMED_FG_MAP[fg]))
        elif isinstance(fg, int):
            v = fg
            if intense and 0 <= v <= 7:
                v = v + 8
            codes.append(f"38;5;{v}")
        elif isinstance(fg, tuple):
            r,g,b = fg
            codes.append(f"38;2;{r};{g};{b}")
    # bg
    if bg is not None:
        if isinstance(bg, str):
            if intense:
                v = BRIGHT_BG_MAP[bg]
                codes.append(f"48;5;{v}")
            else:
                codes.append(str(NAMED_BG_MAP[bg]))
        elif isinstance(bg, int):
            v = bg
            if intense and 0 <= v <= 7:
                v = v + 8
            codes.append(f"48;5;{v}")
        elif isinstance(bg, tuple):
            r,g,b = bg
            codes.append(f"48;2;{r};{g};{b}")
    return codes

def style_to_esc(style):
    codes = ansi_for_style(style)
    if not codes:
        return ""
    # each code as separate ESC
    esc = ""
    for c in codes:
        esc += f"\x1b[{c}m"
    return esc

# Tokenization
def tokenize(s):
    toks=[]
    i=0
    n=len(s)
    while i<n:
        c=s[i]
        if c.isalnum() or c=='_':
            j=i+1
            while j<n and (s[j].isalnum() or s[j]=='_'):
                j+=1
            toks.append(s[i:j])
            i=j
        elif c==' ' or c=='\t':
            j=i+1
            while j<n and (s[j]==' ' or s[j]=='\t'):
                j+=1
            toks.append(s[i:j])
            i=j
        elif c=='\n':
            toks.append('\n')
            i+=1
        else:
            toks.append(c)
            i+=1
    return toks

def build_tokens(lines):
    toks=[]
    for idx, line in enumerate(lines):
        toks.extend(tokenize(line))
        if idx != len(lines)-1:
            toks.append('\n')
    return toks

def lcs_common(r_tokens, a_tokens):
    n=len(r_tokens); m=len(a_tokens)
    # DP for prefix
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(1,n+1):
        for j in range(1,m+1):
            if r_tokens[i-1]==a_tokens[j-1]:
                dp[i][j]=dp[i-1][j-1]+1
            else:
                if dp[i-1][j] >= dp[i][j-1]:
                    dp[i][j]=dp[i-1][j]
                else:
                    dp[i][j]=dp[i][j-1]
    # backtrack from n,m
    i=n; j=m
    common_r=set(); common_a=set()
    while i>0 and j>0:
        if r_tokens[i-1]==a_tokens[j-1] and dp[i][j]==dp[i-1][j-1]+1:
            common_r.add(i-1); common_a.add(j-1); i-=1; j-=1
        elif dp[i-1][j] >= dp[i][j-1]:
            i-=1
        else:
            j-=1
    return common_r, common_a

# Hunk header parsing
HUNK_RE = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")

def parse_hunk_header(line):
    m=HUNK_RE.match(line)
    if not m:
        return None
    old_start=int(m.group(1))
    old_len=m.group(2)
    new_start=int(m.group(3))
    new_len=m.group(4)
    if old_len is None:
        old_len=1
    else:
        old_len=int(old_len)
    if new_len is None:
        new_len=1
    else:
        new_len=int(new_len)
    # rest of line after @@ ... @@ is ignored for numbers
    return (old_start, old_len, new_start, new_len)

def digits(n):
    return len(str(n)) if n>0 else 1

def compute_widths(old_start, old_len, new_start, new_len, style_name):
    # style_name: "compact","aligned","fixed" or None
    if old_len==0:
        w_old=0
    else:
        old_max = old_start + old_len -1
        w_old = len(str(old_max))
    if new_len==0:
        w_new=0
    else:
        new_max = new_start + new_len -1
        w_new = len(str(new_max))
    if old_len>0 and new_len>0:
        # both present
        per_side = max(w_old, w_new)
        if style_name=="fixed":
            per_side = max(3, per_side)
        total_width = per_side*2+1
        return w_old, w_new, per_side, total_width
    else:
        # single side
        per_side = w_old if w_old>0 else w_new
        if style_name=="fixed":
            per_side = max(3, per_side)
        # for compact/aligned single side, per_side is just w
        return w_old, w_new, per_side, per_side

def format_numbers(line_type, old_num, new_num, w_old, w_new, per_side, total_width, style_name, old_len, new_len):
    # line_type: "context","removed","added"
    # For two-sided context etc.
    # Returns numbers_str without tab, but caller adds tab for aligned
    if old_len>0 and new_len>0:
        # two-sided
        if line_type=="context":
            if old_num==new_num:
                # single number centered to total_width
                return f"{old_num:>{total_width}}"
            else:
                return f"{old_num:>{per_side}} {new_num:>{per_side}}"
        elif line_type=="removed":
            return f"{old_num:>{per_side}}{' '*(per_side+1)}"
        elif line_type=="added":
            return f"{' '*(per_side+1)}{new_num:>{per_side}}"
    else:
        # single side
        if line_type=="context":
            # Should not happen for single side context? But if one side len zero, there is no context? Actually hunk with one side zero has no context? But we still handle.
            # For single side, context would be? If old_len==0, context would be added? But header says one side zero, so context lines would still have numbers for the present side only? Let's just handle.
            if old_len>0:
                return f"{old_num:>{per_side}}"
            else:
                return f"{new_num:>{per_side}}"
        elif line_type=="removed":
            return f"{old_num:>{per_side}}"
        elif line_type=="added":
            return f"{new_num:>{per_side}}"
    return ""

# Main processing
def process_lines(lines, has_newline_list, line_numbers_style, face_styles):
    # lines: list of str (without trailing \n)
    # has_newline: list bool
    output_parts=[]
    i=0
    n=len(lines)
    # Keep hunk state
    cur_old_start=None
    cur_old_len=None
    cur_new_start=None
    cur_new_len=None
    cur_old_line=None
    cur_new_line=None
    cur_w_old=cur_w_new=cur_per_side=cur_total=0
    hunk_active=False

    # Precompute face esc strings
    esc_added = style_to_esc(face_styles["added"])
    esc_removed = style_to_esc(face_styles["removed"])
    esc_refine_added = style_to_esc(face_styles["refine-added"])
    esc_refine_removed = style_to_esc(face_styles["refine-removed"])

    # Helper to emit plain line
    def emit_plain(text, has_nl):
        output_parts.append(f"\x1b[0m{text}\x1b[0m")
        if has_nl:
            output_parts.append("\n")
        else:
            # no newline at end, don't add
            pass

    # Helper to emit context with numbers
    # We'll handle inside loop

    idx=0
    while idx < n:
        line = lines[idx]
        has_nl = has_newline_list[idx]
        # Check for hunk header
        hunk = parse_hunk_header(line)
        if hunk is not None:
            old_start, old_len, new_start, new_len = hunk
            cur_old_start, cur_old_len, cur_new_start, cur_new_len = hunk
            cur_old_line = old_start
            cur_new_line = new_start
            # compute widths
            w_old, w_new, per_side, total = compute_widths(old_start, old_len, new_start, new_len, line_numbers_style)
            cur_w_old, cur_w_new, cur_per_side, cur_total = w_old, w_new, per_side, total
            hunk_active=True
            # emit header plain
            emit_plain(line, has_nl)
            idx+=1
            continue
        # Check for file headers
        if line.startswith("--- ") or line.startswith("+++ "):
            hunk_active=False
            emit_plain(line, has_nl)
            idx+=1
            continue
        # If not in hunk, plain
        if not hunk_active:
            # Plain line outside hunk (including diff --git etc)
            emit_plain(line, has_nl)
            idx+=1
            continue
        # Inside hunk
        # Determine line type
        if line.startswith(" ") or line.startswith("\\"):
            # context or no newline marker
            if line.startswith("\\"):
                # \ No newline at end of file
                # It is associated with previous line, but we treat as plain with no numbers? The original shows it as plain with no numbers, just wrapped.
                # Let's emit plain
                emit_plain(line, has_nl)
                idx+=1
                continue
            # context
            content = line[1:]  # after space
            # For line numbers
            if line_numbers_style is not None:
                # format numbers
                nums = format_numbers("context", cur_old_line, cur_new_line, cur_w_old, cur_w_new, cur_per_side, cur_total, line_numbers_style, cur_old_len, cur_new_len)
                # For context, numbers not colored
                # Build output: nums + (tab if aligned) + reset + " " + content
                # But need to handle that nums already includes no color, then we need reset before content
                # For aligned, nums+tab, else nums
                sep = "\t" if line_numbers_style=="aligned" else ""
                # context line output: nums + sep + "\x1b[0m" + " " + content + "\x1b[0m"
                # However for context with numbers, there is no leading reset before nums (as observed)
                out_line = f"{nums}{sep}\x1b[0m {content}\x1b[0m"
                # Actually content is after space prefix: line is " " + content, so we need to include space
                # The " " prefix is part of line[0], content is line[1:], so reconstructed line is " " + content
                # So we have nums + sep + reset + " " + content
                # But note nums for context single number case already is padded to total_width, so that's fine
                output_parts.append(out_line)
                if has_nl:
                    output_parts.append("\n")
            else:
                emit_plain(line, has_nl)
            cur_old_line+=1
            cur_new_line+=1
            idx+=1
            continue
        elif line.startswith("-") and not line.startswith("---"):
            # Collect removed block + following added block
            r_block_lines=[]
            r_indices=[]
            while idx < n and lines[idx].startswith("-") and not lines[idx].startswith("---"):
                r_block_lines.append(lines[idx][1:])
                r_indices.append(idx)
                idx+=1
            a_block_lines=[]
            a_indices=[]
            while idx < n and lines[idx].startswith("+") and not lines[idx].startswith("+++"):
                a_block_lines.append(lines[idx][1:])
                a_indices.append(idx)
                idx+=1
            # Now we have r_block and a_block for this group
            # Compute word diff
            if r_block_lines and a_block_lines:
                # both present
                r_tokens_global = build_tokens(r_block_lines)
                a_tokens_global = build_tokens(a_block_lines)
                common_r, common_a = lcs_common(r_tokens_global, a_tokens_global)
                # Build per line segments
                # For each r line, map
                # Need to map global indices to per line
                # Build offsets
                r_offsets=[]
                offset=0
                for li, lcont in enumerate(r_block_lines):
                    toks = tokenize(lcont)
                    r_offsets.append((offset, len(toks)))
                    offset += len(toks)
                    if li != len(r_block_lines)-1:
                        offset+=1  # newline token
                a_offsets=[]
                offset=0
                for li, lcont in enumerate(a_block_lines):
                    toks = tokenize(lcont)
                    a_offsets.append((offset, len(toks)))
                    offset+=len(toks)
                    if li != len(a_block_lines)-1:
                        offset+=1
                # For each r line, generate segments
                r_line_segments=[]
                for li, lcont in enumerate(r_block_lines):
                    start, cnt = r_offsets[li]
                    toks = tokenize(lcont)
                    segs=[]
                    cur_flag=None
                    cur_text=""
                    for pos, tok in enumerate(toks):
                        gidx = start+pos
                        is_common = gidx in common_r
                        if cur_flag is None:
                            cur_flag=is_common
                            cur_text=tok
                        elif is_common==cur_flag:
                            cur_text+=tok
                        else:
                            segs.append((cur_text, cur_flag))
                            cur_flag=is_common
                            cur_text=tok
                    if cur_text!="" or cur_flag is not None:
                        # if line was empty, cur_text may be "" with cur_flag False? Need handling
                        if toks==[]:
                            # empty line: treat as refined empty
                            segs.append(("", False))
                        else:
                            segs.append((cur_text, cur_flag))
                    elif lcont=="":
                        segs.append(("", False))
                    r_line_segments.append(segs)
                # similarly for a
                a_line_segments=[]
                for li, lcont in enumerate(a_block_lines):
                    start, cnt = a_offsets[li]
                    toks = tokenize(lcont)
                    segs=[]
                    cur_flag=None
                    cur_text=""
                    for pos, tok in enumerate(toks):
                        gidx=start+pos
                        is_common=gidx in common_a
                        if cur_flag is None:
                            cur_flag=is_common
                            cur_text=tok
                        elif is_common==cur_flag:
                            cur_text+=tok
                        else:
                            segs.append((cur_text, cur_flag))
                            cur_flag=is_common
                            cur_text=tok
                    if cur_text!="" or cur_flag is not None:
                        if toks==[]:
                            segs.append(("", False))
                        else:
                            segs.append((cur_text, cur_flag))
                    elif lcont=="":
                        segs.append(("", False))
                    a_line_segments.append(segs)
            elif r_block_lines and not a_block_lines:
                # removed only: all refined
                r_line_segments=[]
